import React, { useState } from 'react';
import { TOP_HEADER_PX } from '../config/thoughtspot';

const BLUE  = '#1E5DEB';
const NAVY  = '#071331';
const TEXT  = '#1f2124';
const TEXT2 = '#515962';
const BG    = '#FFFFFF';
const BG2   = '#F4F6FB';
const BORDER = 'rgba(30,93,235,0.10)';
const GREEN  = '#16a34a';
const RED    = '#dc2626';

// ─── Sparkline ───────────────────────────────────────────────────────────────

function Sparkline({ data, color = BLUE, height = 56 }: { data: number[]; color?: string; height?: number }) {
  const W = 220;
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;
  const pad = 4;

  const pts = data.map((v, i) => ({
    x: (i / (data.length - 1)) * W,
    y: height - pad - ((v - min) / range) * (height - pad * 2),
  }));

  const line = pts.map((p, i) => `${i === 0 ? 'M' : 'L'}${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');
  const area = `${line} L${W},${height} L0,${height} Z`;
  const lastPt = pts[pts.length - 1];
  const gradId = `g${color.replace('#', '')}${height}`;

  return (
    <svg viewBox={`0 0 ${W} ${height}`} preserveAspectRatio="none" style={{ width: '100%', height }}>
      <defs>
        <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity="0.14" />
          <stop offset="100%" stopColor={color} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={area} fill={`url(#${gradId})`} />
      <path d={line} fill="none" stroke={color} strokeWidth="1.6" strokeLinejoin="round" />
      <circle cx={lastPt.x} cy={lastPt.y} r="3.5" fill={color} />
    </svg>
  );
}

// ─── KPI card ────────────────────────────────────────────────────────────────

interface KpiCard {
  title: string;
  period: string;
  value: string;
  delta: string;
  deltaDir: 'up' | 'down' | 'neutral';
  deltaGood: boolean;   // is up good for this metric?
  prevLabel: string;
  data: number[];
  badge?: string;
}

function KpiCardView({ kpi }: { kpi: KpiCard }) {
  const isPositive = kpi.deltaDir === 'up' ? kpi.deltaGood : !kpi.deltaGood;
  const deltaColor = kpi.deltaDir === 'neutral' ? TEXT2 : isPositive ? GREEN : RED;
  const arrow = kpi.deltaDir === 'up' ? '↑' : kpi.deltaDir === 'down' ? '↓' : '→';
  const sparkColor = kpi.deltaDir === 'neutral' ? BLUE : isPositive ? BLUE : '#e55';

  return (
    <div
      style={{
        flex: '1 1 0',
        minWidth: 180,
        backgroundColor: BG,
        border: `1px solid ${BORDER}`,
        borderRadius: 10,
        padding: '1rem 1rem 0.75rem',
        display: 'flex',
        flexDirection: 'column',
        gap: 0,
      }}
    >
      <div style={{ fontSize: 12, fontWeight: 600, color: TEXT, marginBottom: 2 }}>{kpi.title}</div>
      <div style={{ fontSize: 11, color: TEXT2, marginBottom: 8 }}>{kpi.period}</div>

      <div style={{ fontSize: 28, fontWeight: 800, color: NAVY, letterSpacing: '-0.04em', lineHeight: 1, marginBottom: 6 }}>
        {kpi.value}
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 4, marginBottom: 10 }}>
        <span
          style={{
            display: 'inline-flex', alignItems: 'center', gap: 2,
            backgroundColor: isPositive ? 'rgba(22,163,74,0.10)' : kpi.deltaDir === 'neutral' ? BG2 : 'rgba(220,38,38,0.08)',
            color: deltaColor,
            borderRadius: 4, padding: '2px 6px', fontSize: 11, fontWeight: 600,
          }}
        >
          {arrow} {kpi.delta}
        </span>
        <span style={{ fontSize: 11, color: TEXT2 }}>vs {kpi.prevLabel}</span>
      </div>

      {kpi.badge && (
        <div style={{ fontSize: 10, fontWeight: 600, color: isPositive ? GREEN : RED, marginBottom: 4, textAlign: 'right' }}>
          {kpi.badge}
        </div>
      )}

      <Sparkline data={kpi.data} color={sparkColor} />
    </div>
  );
}

// ─── Cadence row ─────────────────────────────────────────────────────────────

interface Cadence {
  id: string;
  name: string;
  icon: React.ReactNode;
  stat1Label: string; stat1Value: string;
  stat2Label: string; stat2Value: string;
  stat3Label: string; stat3Value: string;
  kpis: KpiCard[];
}

function CadenceRow({ cadence, defaultOpen = false }: { cadence: Cadence; defaultOpen?: boolean }) {
  const [open, setOpen] = useState(defaultOpen);

  return (
    <div style={{ backgroundColor: BG, border: `1px solid ${BORDER}`, borderRadius: 12, overflow: 'hidden', marginBottom: 12 }}>
      {/* Header bar */}
      <div
        style={{
          display: 'flex', alignItems: 'center', gap: '1.5rem', flexWrap: 'wrap',
          padding: '0.875rem 1.25rem',
          backgroundColor: BG2,
          borderBottom: open ? `1px solid ${BORDER}` : 'none',
        }}
      >
        {/* Icon + name */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, flex: '0 0 auto' }}>
          <div style={{ width: 32, height: 32, borderRadius: 8, backgroundColor: BLUE, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
            {cadence.icon}
          </div>
          <span style={{ fontWeight: 700, fontSize: 14, color: NAVY, letterSpacing: '-0.01em' }}>{cadence.name}</span>
        </div>

        {/* Stats */}
        <div style={{ display: 'flex', gap: '2rem', flex: 1, flexWrap: 'wrap' }}>
          {[
            { label: cadence.stat1Label, value: cadence.stat1Value },
            { label: cadence.stat2Label, value: cadence.stat2Value },
            { label: cadence.stat3Label, value: cadence.stat3Value },
          ].map(s => (
            <div key={s.label}>
              <div style={{ fontSize: 9.5, fontWeight: 700, letterSpacing: '0.09em', textTransform: 'uppercase', color: TEXT2 }}>{s.label}</div>
              <div style={{ fontSize: 14, fontWeight: 700, color: NAVY, marginTop: 1 }}>{s.value}</div>
            </div>
          ))}
        </div>

        {/* Toggle button */}
        <button
          type="button"
          onClick={() => setOpen(o => !o)}
          style={{
            display: 'flex', alignItems: 'center', gap: 6,
            backgroundColor: open ? NAVY : BLUE,
            color: '#FFFFFF',
            border: 'none',
            padding: '7px 14px',
            borderRadius: 6,
            fontSize: 12,
            fontWeight: 600,
            cursor: 'pointer',
            flexShrink: 0,
            letterSpacing: '-0.01em',
            transition: 'background 0.15s',
          }}
        >
          {open ? 'Hide insights' : 'Show insights'}
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"
            style={{ transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.2s' }}>
            <polyline points="6 9 12 15 18 9" />
          </svg>
        </button>
      </div>

      {/* Expanded KPI panel */}
      {open && (
        <div style={{ padding: '1rem 1.25rem 1.25rem' }}>
          <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
            {cadence.kpis.map(kpi => (
              <KpiCardView key={kpi.title} kpi={kpi} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Mock data ────────────────────────────────────────────────────────────────

const seed = (n: number) => {
  let x = n;
  return () => { x = (x * 1664525 + 1013904223) & 0xffffffff; return (x >>> 0) / 0xffffffff; };
};

const wave = (base: number, volatility: number, n: number, rng: () => number) =>
  Array.from({ length: n }, (_, i) => +(base + Math.sin(i / 3) * volatility * 0.4 + (rng() - 0.5) * volatility).toFixed(2));

const r1 = seed(42); const r2 = seed(77); const r3 = seed(13); const r4 = seed(99);
const r5 = seed(55); const r6 = seed(28); const r7 = seed(63); const r8 = seed(17);
const r9 = seed(34); const r10 = seed(88); const r11 = seed(51); const r12 = seed(72);

const CADENCES: Cadence[] = [
  {
    id: 'invoice-automation',
    name: 'Invoice Automation',
    icon: (
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
        <polyline points="14 2 14 8 20 8" />
        <line x1="16" y1="13" x2="8" y2="13" />
        <line x1="16" y1="17" x2="8" y2="17" />
        <polyline points="10 9 9 9 8 9" />
      </svg>
    ),
    stat1Label: 'Invoices Processed', stat1Value: '1,247',
    stat2Label: 'Touchless Rate',     stat2Value: '94.2%',
    stat3Label: 'Cash Discount',      stat3Value: '€42.5K',
    kpis: [
      {
        title: 'Touchless Rate',
        period: 'Week of 03/24/2026',
        value: '94.2%',
        delta: '3.1%',
        deltaDir: 'up',
        deltaGood: true,
        prevLabel: 'Week of 03/17/2026 (91.1%)',
        data: wave(88, 8, 24, r1),
      },
      {
        title: 'Avg Processing Time',
        period: 'Week of 03/24/2026',
        value: '0.8 days',
        delta: '11.1%',
        deltaDir: 'down',
        deltaGood: true,
        prevLabel: 'Week of 03/17/2026 (0.9d)',
        data: wave(1.8, 0.6, 24, r2).map(v => +(1.8 - v * 0.1 + 0.8).toFixed(2)),
      },
      {
        title: 'Weekly Invoice Volume',
        period: 'Week of 03/24/2026',
        value: '1,247',
        delta: '8.5%',
        deltaDir: 'up',
        deltaGood: true,
        prevLabel: 'Week of 03/17/2026 (1,149)',
        data: wave(1100, 200, 24, r3),
        badge: 'Above expected',
      },
      {
        title: 'Exception Rate',
        period: 'Week of 03/24/2026',
        value: '5.8%',
        delta: '6.5%',
        deltaDir: 'down',
        deltaGood: true,
        prevLabel: 'Week of 03/17/2026 (6.2%)',
        data: wave(8, 3, 24, r4),
      },
    ],
  },
  {
    id: 'ap-performance',
    name: 'AP Performance',
    icon: (
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <polyline points="22 7 13.5 15.5 8.5 10.5 2 17" />
        <polyline points="16 7 22 7 22 13" />
      </svg>
    ),
    stat1Label: 'Invoices Paid',     stat1Value: '892',
    stat2Label: 'On-Time Rate',      stat2Value: '89.4%',
    stat3Label: 'Duplicate Alerts',  stat3Value: '3',
    kpis: [
      {
        title: 'On-Time Payment Rate',
        period: 'Week of 03/24/2026',
        value: '89.4%',
        delta: '2.3%',
        deltaDir: 'up',
        deltaGood: true,
        prevLabel: 'Week of 03/17/2026 (87.4%)',
        data: wave(85, 6, 24, r5),
      },
      {
        title: 'Cash Discount Captured',
        period: 'Week of 03/24/2026',
        value: '€42.5K',
        delta: '18.7%',
        deltaDir: 'up',
        deltaGood: true,
        prevLabel: 'Week of 03/17/2026 (€35.8K)',
        data: wave(35000, 9000, 24, r6),
        badge: 'Above expected',
      },
      {
        title: 'Duplicate Detections',
        period: 'Week of 03/24/2026',
        value: '3',
        delta: '40.0%',
        deltaDir: 'down',
        deltaGood: true,
        prevLabel: 'Week of 03/17/2026 (5)',
        data: wave(5, 3, 24, r7),
      },
      {
        title: 'Supplier SLA Compliance',
        period: 'Week of 03/24/2026',
        value: '96.4%',
        delta: '1.2%',
        deltaDir: 'up',
        deltaGood: true,
        prevLabel: 'Week of 03/17/2026 (95.3%)',
        data: wave(93, 4, 24, r8),
      },
    ],
  },
  {
    id: 'procurement',
    name: 'Procurement Efficiency',
    icon: (
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="9" cy="21" r="1" /><circle cx="20" cy="21" r="1" />
        <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6" />
      </svg>
    ),
    stat1Label: 'POs Processed',  stat1Value: '418',
    stat2Label: 'PO Match Rate',  stat2Value: '87.3%',
    stat3Label: 'Cycle Time',     stat3Value: '1.4 days',
    kpis: [
      {
        title: 'PO Match Rate',
        period: 'Week of 03/24/2026',
        value: '87.3%',
        delta: '2.8%',
        deltaDir: 'up',
        deltaGood: true,
        prevLabel: 'Week of 03/17/2026 (84.9%)',
        data: wave(82, 8, 24, r9),
      },
      {
        title: 'Approval Cycle Time',
        period: 'Week of 03/24/2026',
        value: '1.4 days',
        delta: '12.5%',
        deltaDir: 'down',
        deltaGood: true,
        prevLabel: 'Week of 03/17/2026 (1.6d)',
        data: wave(2.2, 0.7, 24, r10).map(v => Math.max(0.5, v)),
      },
      {
        title: '3-Way Match Rate',
        period: 'Week of 03/24/2026',
        value: '72.1%',
        delta: '3.4%',
        deltaDir: 'down',
        deltaGood: false,
        prevLabel: 'Week of 03/17/2026 (74.7%)',
        data: wave(74, 6, 24, r11),
      },
      {
        title: 'Non-PO Invoice Share',
        period: 'Week of 03/24/2026',
        value: '14.3%',
        delta: '1.8%',
        deltaDir: 'up',
        deltaGood: false,
        prevLabel: 'Week of 03/17/2026 (12.7%)',
        data: wave(12, 4, 24, r12),
      },
    ],
  },
];

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function CadencesPage() {
  const [refreshKey, setRefreshKey] = useState(0);

  return (
    <div style={{ backgroundColor: BG, minHeight: `calc(100vh - ${TOP_HEADER_PX}px)` }}>
      <div style={{ maxWidth: 1100, margin: '0 auto', padding: '2rem 2.5rem 3rem' }}>

        {/* Page header */}
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: '1.75rem', gap: 16, flexWrap: 'wrap' }}>
          <div>
            <h1 style={{ fontSize: 26, fontWeight: 800, color: NAVY, letterSpacing: '-0.03em', margin: '0 0 4px' }}>
              Cadences
            </h1>
            <p style={{ fontSize: 13, color: TEXT2, margin: 0 }}>
              Select a cadence to see its KPI performance inline — filtered by process area
            </p>
          </div>
          <button
            type="button"
            onClick={() => setRefreshKey(k => k + 1)}
            style={{
              display: 'flex', alignItems: 'center', gap: 6,
              backgroundColor: BG, color: TEXT,
              border: `1px solid ${BORDER}`,
              padding: '8px 16px', borderRadius: 7,
              fontSize: 13, fontWeight: 600, cursor: 'pointer',
            }}
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="23 4 23 10 17 10" />
              <polyline points="1 20 1 14 7 14" />
              <path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15" />
            </svg>
            Refresh
          </button>
        </div>

        {/* Cadence rows */}
        <div key={refreshKey}>
          {CADENCES.map((c, i) => (
            <CadenceRow key={c.id} cadence={c} defaultOpen={i === 0} />
          ))}
        </div>
      </div>
    </div>
  );
}
